#rf-root,.hf-root{--x3:#414b5a;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 5.5s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.ba-hd{position:absolute;left:90px;right:90px;top:260px;font-size:88px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:1;text-align:center}
.ba{position:absolute;left:70px;right:70px;top:520px;height:1000px;border-radius:44px;overflow:hidden;box-shadow:0 0 0 2px color-mix(in srgb,var(--rf-text) 8%,transparent);animation:k-rise .9s cubic-bezier(.16,1,.3,1) 0.1s both}
.ba-s{position:absolute;inset:0;padding:60px}
.ba-b{background:color-mix(in srgb,var(--rf-surface) 85%,#777);filter:saturate(.3)}
.ba-a{background:var(--rf-surface);clip-path:inset(0 0 0 100%);animation:ba-w 1.4s cubic-bezier(.76,0,.24,1) 1.7s both}
@keyframes ba-w{to{clip-path:inset(0 0 0 0)}}
.ba-div{position:absolute;top:0;bottom:0;left:100%;width:6px;margin-left:-3px;background:var(--rf-text);animation:ba-d 1.4s cubic-bezier(.76,0,.24,1) 1.7s both;z-index:4}
@keyframes ba-d{to{left:0}}
.ba-div span{position:absolute;top:50%;left:50%;width:100px;height:100px;margin:-50px 0 0 -50px;border-radius:50%;background:var(--rf-text);color:var(--rf-bg);display:flex;align-items:center;justify-content:center;transform:rotate(180deg)}
.ba-tag{display:inline-block;font:500 30px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;padding:16px 24px;border-radius:14px;background:color-mix(in srgb,var(--rf-text) 12%,transparent)}
.ba-a .ba-tag{background:var(--rf-accent);color:var(--rf-bg)}
.ba-s ul{position:absolute;left:60px;right:60px;bottom:60px;margin:0;padding:0;list-style:none}
.ba-s li{font-size:42px;font-weight:600;margin-top:16px}
.ba-b li{color:color-mix(in srgb,var(--rf-text) 60%,transparent);text-decoration:line-through;text-decoration-thickness:3px}
.ba-ui{margin-top:60px}.ba-ui b{display:block;height:34px;border-radius:10px;margin-bottom:22px;background:color-mix(in srgb,var(--rf-text) 22%,transparent)}
.ba-ui.mess b:nth-child(odd){transform:rotate(-1.5deg)}
.ba-card{height:130px;border-radius:24px;margin-top:26px;background:color-mix(in srgb,var(--rf-text) 10%,transparent);box-shadow:inset 8px 0 0 var(--rf-accent)}
.ba-ch{display:flex;align-items:flex-end;gap:22px;height:420px;margin-top:60px}.ba-ch i{flex:1;border-radius:14px 14px 4px 4px;background:color-mix(in srgb,var(--rf-text) 30%,transparent)}
.ba-a .ba-ch i{background:color-mix(in srgb,var(--rf-text) 30%,transparent)}.ba-a .ba-ch i:last-child{background:var(--rf-accent)}
.ba-room{position:relative;height:460px;margin-top:40px;border-radius:30px;background:color-mix(in srgb,var(--rf-text) 8%,transparent);overflow:hidden}
.ba-room i{position:absolute;display:block}
.ba-room .win{left:8%;top:10%;width:34%;height:42%;border-radius:12px;background:color-mix(in srgb,var(--rf-text) 20%,transparent)}
.ba-room .sofa{left:30%;bottom:10%;width:58%;height:26%;border-radius:30px 30px 14px 14px;background:color-mix(in srgb,var(--rf-text) 25%,transparent)}
.ba-room .lamp{right:8%;top:16%;width:70px;height:70px;border-radius:50%;background:color-mix(in srgb,var(--rf-text) 25%,transparent)}
.ba-room .plant{left:10%;bottom:10%;width:80px;height:160px;border-radius:40px 40px 10px 10px;background:color-mix(in srgb,var(--rf-text) 18%,transparent)}
.ba-room.warm{background:radial-gradient(38% 46% at 88% 20%,rgba(255,210,122,.32),transparent 72%),color-mix(in srgb,#ffb35c 12%,var(--rf-surface))}
.ba-room.warm .win{background:color-mix(in srgb,#ffd9a0 45%,var(--rf-surface))}
.ba-room.warm .sofa{background:var(--rf-accent)}.ba-room.warm .lamp{background:#ffd27a}.ba-room.warm .plant{background:#3fbf7f}

